/* Placeholder html2pdf.bundle.min.js
   Minimal shim exposing a html2pdf() function used to trigger PDF generation in the app.
   Replace with the official html2pdf.bundle.min.js to enable full-featured PDF export.
*/
window.html2pdf = window.html2pdf || function(){
  return {
    from: function(el){
      return {
        save: function(filename){
          // very small fallback: convert element's innerText to a text file as a naive "pdf" fallback
          try{
            const content = (el && el.innerText) ? el.innerText : String(el);
            const blob = new Blob([content], { type: 'text/plain' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a'); a.href = url; a.download = filename || 'export.txt'; document.body.appendChild(a); a.click(); a.remove();
            setTimeout(()=>URL.revokeObjectURL(url), 1000);
          }catch(e){ console.warn('html2pdf stub failed', e); }
        }
      };
    }
  };
};

/* End of placeholder html2pdf.bundle.min.js */